    id ?? value ?? element.props?.['data-value'] ?? element.props?.id ?? itemId;
  const isActive = activeValue === childValue;
  const handOff = activeValue !== null;
  const handedTo =
    isActive && previousValue !== null && previousValue !== childValue;
  const [surfaceKey, setSurfaceKey] = React.useState('rest');
  const wantedKey = handedTo ? `to-${changes}` : surfaceKey;
  if (wantedKey !== surfaceKey) setSurfaceKey(wantedKey);
  const isDisabled = disabled === undefined ? contextDisabled : disabled;
  const { tempo } = useMotionTokens();
  const ownTransition = useTempoTransition(transition);
  const itemTransition = ownTransition ?? contextTransition;
  const itemExitDelay =
    exitDelay === undefined ? contextExitDelay : exitDelay * tempo;
  const fade = {
    hidden: (handingOff: boolean) => ({
      opacity: 0,
      transition: handingOff
        ? { duration: 0 }
        : {
            ...itemTransition,
            delay: (itemTransition?.delay ?? 0) + (itemExitDelay ?? 0) / 1000,
          },
    }),
    shown: { opacity: 1 },
  };

  const canHover = useCanHover();

  const localRef = React.useRef<HTMLDivElement>(null);
  React.useImperativeHandle(ref, () => localRef.current as HTMLDivElement);

  const childRef = React.isValidElement(children)
    ? (children as React.ReactElement<ExtendedChildProps>).props.ref
    : undefined;
  const refCallback = React.useMemo(
    () => mergeRefs<HTMLElement>(localRef as React.Ref<HTMLElement>, childRef),
    [childRef],
  );

  React.useEffect(() => {
    if (mode !== 'parent') return;
    let rafId: number;
    let previousBounds: Bounds | null = null;
    const shouldUpdateBounds =
      forceUpdateBounds === true ||
      (contextForceUpdateBounds && forceUpdateBounds !== false);

    const updateBounds = () => {
      if (!localRef.current) return;

      const bounds = localRef.current.getBoundingClientRect();

      if (shouldUpdateBounds) {
        if (
          previousBounds &&
          previousBounds.top === bounds.top &&
          previousBounds.left === bounds.left &&
          previousBounds.width === bounds.width &&
          previousBounds.height === bounds.height
        ) {
          rafId = requestAnimationFrame(updateBounds);
          return;
        }
        previousBounds = bounds;
        rafId = requestAnimationFrame(updateBounds);
      }

      setBounds(bounds);
    };

    let observer: ResizeObserver | undefined;
    if (isActive && isDisabled) clearBounds();
    else if (isActive) {
      updateBounds();
      setActiveClassName(activeClassName ?? '');
      const node = localRef.current;
      if (node && !shouldUpdateBounds) {
        observer = new ResizeObserver(() => updateBounds());
        observer.observe(node);
        const container = node.closest(
          '[data-slot="motion-highlight-container"]',
        );
        if (container) observer.observe(container);
      }
    } else if (!activeValue) clearBounds();

    return () => {
      observer?.disconnect();
      if (shouldUpdateBounds) cancelAnimationFrame(rafId);
    };
  }, [
    mode,
    isActive,
    isDisabled,
    activeValue,
    setBounds,
    clearBounds,
    activeClassName,
    setActiveClassName,
    forceUpdateBounds,
    contextForceUpdateBounds,
  ]);

  if (!React.isValidElement(children)) return children;

  const dataAttributes = {
    'data-active': isActive ? 'true' : 'false',
    'data-disabled': isDisabled,
    'data-value': childValue,
    'data-highlight': true,
  };

  const own = { onClick, onMouseEnter, onMouseLeave } as Pick<
    ExtendedChildProps,
    'onClick' | 'onMouseEnter' | 'onMouseLeave'
  >;
  const handler =
    (
      name: 'onClick' | 'onMouseEnter' | 'onMouseLeave',
      next: string | null,
      active: boolean,
    ) =>
    (e: React.MouseEvent<HTMLDivElement>) => {
      if (active) setActiveValue(next);
      if (asChild) element.props[name]?.(e);
      own[name]?.(e);
    };

  const handlers = {
    onMouseEnter: handler('onMouseEnter', childValue, hover && canHover),
    onMouseLeave: handler('onMouseLeave', null, hover && canHover),
    onClick: handler('onClick', childValue, !hover && click),
  };

  if (asChild) {
    if (mode === 'children') {
      return React.cloneElement(
        element,
        {
          key: childValue,
          ref: refCallback,
          className: cn('relative', element.props.className),
          ...getNonOverridingDataAttributes(element, {
            ...dataAttributes,
            'data-slot': 'motion-highlight-item-container',
          }),
          ...props,
          ...handlers,
        },
        <>
          <AnimatePresence initial={false} custom={handOff}>
            {isActive && !isDisabled && (
              <motion.div
                key={wantedKey}
                layoutId={`transition-background-${contextId}`}
                data-slot="motion-highlight"
                style={{
                  position: 'absolute',
                  zIndex: 0,
                  ...contextStyle,
                  ...style,
                }}
                className={cn(contextClassName, activeClassName)}
                transition={itemTransition}
                layoutCrossfade={false}
                custom={handOff}
                variants={fade}
                initial={handedTo ? false : 'hidden'}
                animate="shown"
                exit="hidden"
                {...dataAttributes}
              />
            )}
          </AnimatePresence>

          <Component
            data-slot="motion-highlight-item"
            style={{ position: 'relative', zIndex: 1 }}
            className={className}
            {...dataAttributes}
          >
            {children}
          </Component>
        </>,
      );
    }

    return React.cloneElement(element, {
      ref: refCallback,
      ...getNonOverridingDataAttributes(element, {
        ...dataAttributes,
        'data-slot': 'motion-highlight-item',
      }),
      ...handlers,
    });
  }

  return enabled ? (
    <Component
      key={childValue}
      ref={localRef}
      data-slot="motion-highlight-item-container"
      className={cn(mode === 'children' && 'relative', className)}
      {...dataAttributes}
      {...props}
      {...handlers}
    >
      {mode === 'children' && (
        <AnimatePresence initial={false} custom={handOff}>
          {isActive && !isDisabled && (
            <motion.div
              key={wantedKey}
              layoutId={`transition-background-${contextId}`}
              data-slot="motion-highlight"
              style={{
                position: 'absolute',
                zIndex: 0,
                ...contextStyle,
                ...style,
              }}
              className={cn(contextClassName, activeClassName)}
              transition={itemTransition}
              layoutCrossfade={false}
              custom={handOff}
              variants={fade}
              initial={handedTo ? false : 'hidden'}
              animate="shown"
              exit="hidden"
              {...dataAttributes}
            />
          )}
        </AnimatePresence>
      )}

      {React.cloneElement(element, {
        style: { position: 'relative', zIndex: 1, ...element.props.style },
        className: element.props.className,
        ...getNonOverridingDataAttributes(element, {
          ...dataAttributes,
          'data-slot': 'motion-highlight-item',
        }),
      })}
    </Component>
  ) : (
    children
  );
}

export {
  Highlight,
  HighlightItem,
  useHighlight,
  type HighlightProps,
  type HighlightItemProps,
};

'use client';

import * as React from 'react';
import { useInView, type UseInViewOptions } from 'motion/react';

interface UseIsInViewOptions {
  inView?: boolean;
  inViewOnce?: boolean;
  inViewMargin?: UseInViewOptions['margin'];
}

function useIsInView<T extends HTMLElement = HTMLElement>(
  ref: React.Ref<T>,
  options: UseIsInViewOptions = {},
) {
  const { inView, inViewOnce = false, inViewMargin = '0px' } = options;
  const localRef = React.useRef<T>(null);
  React.useImperativeHandle(ref, () => localRef.current as T);
  const inViewResult = useInView(localRef, {
    once: inViewOnce,
    margin: inViewMargin,
  });
  const isInView = !inView || inViewResult;
  return { ref: localRef, isInView };
}

export { useIsInView, type UseIsInViewOptions };

'use client';

import * as React from 'react';
import {
  motion,
  type TargetAndTransition,
  type Transition,
} from 'motion/react';

import {
  motionTokens,
  useShouldReduceMotion,
  useTempoTransition,
} from '../utils/motion';
import { useStaggeredEnter } from './stagger';

const POPOVER_TRANSITION = motionTokens.spring.pop;
const MENU_TRANSITION = motionTokens.transition.menu;
const MORPH_TRANSITION = motionTokens.spring.morph;

const HIDDEN_SCALE = {
  tooltip: motionTokens.scale.tooltip,
  popover: motionTokens.scale.popover,
  menu: motionTokens.scale.menu,
} as const;
const DEFAULT_TRANSITION = {
  tooltip: POPOVER_TRANSITION,
  popover: POPOVER_TRANSITION,
  menu: MENU_TRANSITION,
} as const;

type AnchoredKind = keyof typeof HIDDEN_SCALE;

type AnchoredAnimationProps = {
  transition?: Transition;
  exitTransition?: Transition;
};

type AnchoredMotionOptions = AnchoredAnimationProps & {
  kind?: AnchoredKind;
  open: boolean;
  keepMounted?: boolean;
  instant?: boolean;
};

type AnchoredMotionProps = {
  initial: false | TargetAndTransition;
  animate: TargetAndTransition;
  exit: TargetAndTransition;
  style?: React.CSSProperties;
  onAnimationComplete?: (definition: unknown) => void;
};

const WARM_WINDOW = 300;

const tooltipGroup = {
  open: new Set<symbol>(),
  warm: false,
  coolDown: undefined as ReturnType<typeof setTimeout> | undefined,
  leaving: new Map<symbol, () => void>(),
};

function useWarmTooltip(open: boolean, enabled: boolean) {
  const [id] = React.useState(() => Symbol('tooltip'));
  const [change, setChange] = React.useState(() => ({
    open,
    atOnce: enabled && open && tooltipGroup.warm,
  }));
  if (change.open !== open) {
    setChange({
      open,
      atOnce:
        enabled &&
        (open
          ? tooltipGroup.warm
          : [...tooltipGroup.open].some((other) => other !== id)),
    });
  }
  const [cut, setCut] = React.useState(false);
  if (open && cut) setCut(false);
  const atOnceRef = React.useRef(change.atOnce);
  React.useLayoutEffect(() => {
    atOnceRef.current = change.atOnce;
  });

  React.useEffect(() => {
    if (!enabled || !open) return;
    tooltipGroup.open.add(id);
    tooltipGroup.warm = true;
    clearTimeout(tooltipGroup.coolDown);
    if (atOnceRef.current)
      for (const hide of tooltipGroup.leaving.values()) hide();
    return () => {
      tooltipGroup.open.delete(id);
      if (tooltipGroup.open.size > 0) return;
      clearTimeout(tooltipGroup.coolDown);
      tooltipGroup.coolDown = setTimeout(() => {
        tooltipGroup.warm = false;
      }, WARM_WINDOW);
    };
  }, [enabled, open, id]);

  React.useEffect(() => {
    if (!enabled || open) return;
    tooltipGroup.leaving.set(id, () => setCut(true));
    return () => {
      tooltipGroup.leaving.delete(id);
    };
  }, [enabled, open, id]);

  return {
    appearAtOnce: open && change.atOnce,
    hideAtOnce: !open && (change.atOnce || cut),
  };
}

function useAnchoredMotion({
  kind = 'popover',
  open,
  keepMounted,
  instant,
  transition,
  exitTransition,
}: AnchoredMotionOptions): AnchoredMotionProps {
  const reduce = useShouldReduceMotion();
  const warmsUp = kind === 'tooltip' && instant === undefined;
  const warm = useWarmTooltip(open, warmsUp);
  const enter = useTempoTransition(transition ?? DEFAULT_TRANSITION[kind]);
  const leave = useTempoTransition(
    exitTransition ?? transition ?? DEFAULT_TRANSITION[kind],
  );
  const quick = useStaggeredEnter(enter);
  const hidden = { opacity: 0, scale: reduce ? 1 : HIDDEN_SCALE[kind] };
  const shown = { opacity: 1, scale: 1 };
  const none = { duration: 0 };

  const [settledClosed, setSettledClosed] = React.useState(
    Boolean(keepMounted) && !open,
  );
  if (open && settledClosed) setSettledClosed(false);

  const appearAtOnce = instant || warm.appearAtOnce;

  return {
    initial: appearAtOnce || !open ? false : hidden,
    animate: open
      ? {
          ...shown,
          transition: appearAtOnce ? none : kind === 'menu' ? quick : enter,
          ...(keepMounted && { visibility: 'visible' }),
        }
      : {
          ...hidden,
          transition: instant ? none : leave,
          ...(keepMounted && settledClosed && { visibility: 'hidden' }),
        },
    exit: { ...hidden, transition: instant ? none : leave },
    style: warm.hideAtOnce ? { visibility: 'hidden' } : undefined,
    onAnimationComplete: keepMounted
      ? (definition) => {
          const target = definition as { opacity?: number };
          if (!open && target.opacity === 0) setSettledClosed(true);
        }
      : undefined,
  };
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type AnyComponent = string | React.ComponentType<any>;
const motionComponents = new Map<AnyComponent, AnyComponent>();

function motionFor(type: AnyComponent): AnyComponent {
  let component = motionComponents.get(type);
  if (!component) {
    component =
      typeof type === 'string'
        ? (motion as unknown as Record<string, AnyComponent>)[type]!
        : (motion.create(type) as AnyComponent);
    motionComponents.set(type, component);
  }
  return component;
}

function mergeRefs<T>(...refs: (React.Ref<T> | undefined)[]) {
  return (node: T | null) => {
    for (const ref of refs) {
      if (typeof ref === 'function') ref(node);
      else if (ref) (ref as React.RefObject<T | null>).current = node;
    }
  };
}

type ElementProps = {
  ref?: React.Ref<HTMLElement>;
  style?: React.CSSProperties;
} & Record<string, unknown>;

function asMotion(element: React.ReactElement, props: ElementProps) {
  const own = element.props as ElementProps;
  const Component = motionFor(
    element.type as AnyComponent,
  ) as React.ElementType;
  return (
    <Component
      {...own}
      {...props}
      ref={mergeRefs(own.ref, props.ref)}
      style={{ ...own.style, ...props.style }}
    />
  );
}

export {
  useAnchoredMotion,
  asMotion,
  mergeRefs,
  POPOVER_TRANSITION,
  MENU_TRANSITION,
  MORPH_TRANSITION,
  HIDDEN_SCALE,
  type AnchoredKind,
  type AnchoredAnimationProps,
  type AnchoredMotionProps,
};

import * as React from 'react';
import type { Transition } from 'motion/react';

import {
  motionTokens,
  toCssTiming,
  useShouldReduceMotion,
  useTempoTransition,
} from '../utils/motion';

const ROWS = [
  '[role^="menuitem"]',
  '[role="option"]',
  '[role="separator"]',
  '[data-slot$="-label"]',
  '[data-slot="navigation-menu-link"]',
  '[data-slot="sidebar-menu-sub-item"]',
].join(',');

const STAGGER = { duration: 0.3, ease: motionTokens.ease.soft, delay: 0.033 };
const SHIFT = 8;
const ARRIVE = { duration: 0.1, ease: motionTokens.ease.out };
const CALM = 10;
const STAGGER_ID = 'animate-ui-stagger';

type StaggerTiming = { duration: number; easing: string; step: number };

function opacityOf(el: Element) {
  let opacity = 1;
  for (let node: Element | null = el; node; node = node.parentElement)
    opacity *= Number(getComputedStyle(node).opacity);
  return opacity;
}

function rowsOf(root: HTMLElement) {
  const rows = [...root.querySelectorAll<HTMLElement>(ROWS)].filter(
    (row) => !row.closest('[data-animate-ui-handoff]'),
  );
  return rows.filter(
    (row) => !rows.some((other) => other !== row && other.contains(row)),
  );
}

function animateRows(rows: HTMLElement[], timing: StaggerTiming) {
  const shift =
    rows[0] && getComputedStyle(rows[0]).direction === 'rtl' ? -SHIFT : SHIFT;
  const step =
    rows.length > CALM
      ? timing.step * Math.sqrt(CALM / rows.length)
      : timing.step;
  return rows.map((row, index) =>
    row.animate(
      [
        {
          opacity: 0,
          filter: motionTokens.blur.surface,
          translate: `${shift}px 0`,
        },
        // No opacity here: it ends on the row's own, a disabled one's 50% or one the library shows late.
        { filter: 'blur(0px)', translate: '0 0' },
      ],
      {
        duration: timing.duration,
        easing: timing.easing,
        delay: index * step,
        fill: 'backwards',
        id: STAGGER_ID,
      },
    ),
  );
}

/** How long until `row` lands from its stagger (0 when it isn't staggering). */
function staggerLeft(row: Element | null) {
  const animation = row
    ?.getAnimations()
    .find((candidate) => candidate.id === STAGGER_ID);
  if (!animation || animation.playState === 'finished') return 0;
  const end = animation.effect?.getComputedTiming().endTime;
  return Math.max(0, Number(end ?? 0) - Number(animation.currentTime ?? 0));
}

/**
 * A just-opened list's rows slide in from the side one after another, out of a blur;
 * rows a library renders a commit later (React Aria's) as they come, before
 * they're painted. `stop` shows them all.
 */
/**
 * Rows slid aside widen what their list can scroll: a library scrolling the
 * chosen one into view (Base UI's combobox) would scroll sideways too, then
 * back as they land. The lists keep their horizontal scroll meanwhile.
 */
function holdScrollX(root: HTMLElement) {
  const lefts = new Map<Element, number>();
  for (const el of [root, ...root.querySelectorAll('*')])
    lefts.set(el, el.scrollLeft);
  const hold = (event: Event) => {
    const target = event.target as Element;
    const left = lefts.get(target);
    if (left !== undefined && target.scrollLeft !== left)
      target.scrollLeft = left;
  };
  root.addEventListener('scroll', hold, true);
  return () => root.removeEventListener('scroll', hold, true);
}

function staggerRows(root: HTMLElement, timing: StaggerTiming) {
  let animations: Animation[] = [];
  let observer: MutationObserver | null = null;
  const release = holdScrollX(root);
  const start = (rows: HTMLElement[]) => {
    animations = animateRows(rows, timing);
    void Promise.all(animations.map((animation) => animation.finished)).then(
      release,
      release,
    );
  };
  const rows = rowsOf(root);
  if (rows.length) start(rows);
  else {
    observer = new MutationObserver(() => {
      const late = rowsOf(root);
      if (!late.length) return;
      observer?.disconnect();
      observer = null;
      start(late);
    });
    observer.observe(root, { childList: true, subtree: true });
    setTimeout(() => {
      if (!observer) return;
      observer.disconnect();
      release();
    }, 300);
  }
  return () => {
    observer?.disconnect();
    for (const animation of animations) animation.finish();
    release();
  };
}

/** Staggers `el`'s rows if it opens from closed: it's still transparent. */
function staggerFromClosed(el: HTMLElement, timing: StaggerTiming) {
  return opacityOf(el) > 0.05 ? null : staggerRows(el, timing);
}

function useStaggerTiming() {
  const transition = useTempoTransition(STAGGER);
  const timingRef = React.useRef<StaggerTiming>(null!);
  React.useLayoutEffect(() => {
    timingRef.current = {
      ...toCssTiming(transition),
      step: (transition.delay ?? 0) * 1000,
    };
  });
  return timingRef;
}

/**
 * Staggers the rows of `ref`'s list as it opens from closed (it starts
 * transparent, or `fresh` says so), not as it comes back while closing or
 * takes over another menu's popover.
 */
function useStaggerOnOpen(
  ref: React.RefObject<HTMLElement | null>,
  open: boolean,
  options: {
    skip?: boolean;
    fresh?: boolean;
    closed?: (el: HTMLElement) => boolean;
  } = {},
) {
  const reduce = useShouldReduceMotion();
  const timingRef = useStaggerTiming();
  const {
    skip = false,
    fresh,
    closed = (el) => opacityOf(el) <= 0.05,
  } = options;
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!open || reduce || skip || !el) return;
    if (fresh === undefined ? !closed(el) : !fresh) return;
    return staggerRows(el, timingRef.current);
    // eslint-disable-next-line react-hooks/exhaustive-deps, @eslint-react/exhaustive-deps
  }, [open]);
}

/** A sidebar's submenu, in a collapsible panel: its sub-items stagger as it unfolds from closed. */
function useSubmenuStagger(
  ref: React.RefObject<HTMLElement | null>,
  open: boolean,
) {
  useStaggerOnOpen(ref, open, {
    closed: (el) =>
      el.offsetHeight < 1 &&
      !!el.querySelector('[data-slot="sidebar-menu-sub"]'),
  });
}

/** A list whose rows stagger: its box is there at once (opacity), its rows bring the fade; under reduced motion, nothing staggers and it fades. */
function useStaggeredEnter(enter: Transition): Transition {
  const reduce = useShouldReduceMotion();
  const arrive = useTempoTransition(ARRIVE);
  return reduce ? enter : { ...enter, opacity: arrive };
}

/**
 * A sidebar submenu's panel is there at once (opacity, blur) while it unfolds,
 * so its sub-items bring the fade: added over the panel's own animation, after it starts.
 */
function quickSubmenuPanel(el: HTMLElement | null) {
  if (!el?.querySelector('[data-slot="sidebar-menu-sub"]')) return;
  queueMicrotask(() => {
    const ends = el
      .getAnimations()
      .map((animation) =>
        Number(animation.effect?.getComputedTiming().endTime ?? 0),
      );
    const total = Math.max(300, ...ends);
    const settled = { opacity: 1, filter: 'blur(0px)' };
    el.animate(
      [
        { ...settled, offset: Math.min(1, 100 / total) },
        { ...settled, offset: 1 },
      ],
      { duration: total, easing: 'ease-out' },
    );
  });
}

export {
  quickSubmenuPanel,
  staggerFromClosed,
  useStaggeredEnter,
  staggerLeft,
  useSubmenuStagger,
  staggerRows,
  useStaggerOnOpen,
  useStaggerTiming,
  type StaggerTiming,
};

