import {
  BottomNavigation,
  BottomNavigationAccessory,
  BottomNavigationHighlight,
  BottomNavigationHighlightItem,
  BottomNavigationItem,
  BottomNavigationLabel,
} from '@animate-ui/react/primitives/bottom-navigation';

const ITEMS = [
  { value: 'home', href: '/', label: 'Home', icon: <HomeIcon /> },
  { value: 'search', href: '/search', label: 'Search', icon: <SearchIcon /> },
];

export function AppNavigation() {
  return (
    <BottomNavigation
      defaultValue="home"
      scrollBehavior="minimize"
      aria-label="Main"
      className="fixed inset-x-0 bottom-4 mx-auto flex w-fit items-center gap-2"
    >
      <BottomNavigationHighlight className="absolute inset-0 rounded-full bg-muted">
        <ul className="flex rounded-full border bg-background p-1.5">
          {ITEMS.map((item) => (
            <li key={item.value}>
              <BottomNavigationHighlightItem value={item.value}>
                <BottomNavigationItem
                  value={item.value}
                  href={item.href}
                  className="flex items-center px-4 py-2"
                >
                  {item.icon}
                  <BottomNavigationLabel className="pl-2">
                    {item.label}
                  </BottomNavigationLabel>
                </BottomNavigationItem>
              </BottomNavigationHighlightItem>
            </li>
          ))}
        </ul>
      </BottomNavigationHighlight>
      <BottomNavigationAccessory className="rounded-full border bg-background p-1.5">
        <button className="size-11 rounded-full hover:bg-muted">+</button>
      </BottomNavigationAccessory>
    </BottomNavigation>
  );
}
